const pendingQ = $('Lookup MQL1').item.json.pending_question || '';
const userMessage = (
  $('WhatsApp Trigger1').item.json.messages?.[0]?.text?.body ||
  $('WhatsApp Trigger1').item.json.messages?.[0]?.button?.payload || ''
).trim();

function _norm(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
const normMsg = _norm(userMessage);

// Tipos de respuesta inválida
const testWords    = ['prueba','test','hola','hello','hi','hey','demo','probando','123','asdf','qwerty'];
const vagueWords   = ['ninguna','ninguno','no sé','no se','nada','no tengo','desconozco','no lo sé','no lo se','ninguna idea','no idea'];
const ambigWords   = ['todas','todos','varias','varios','cualquiera','todo','de todo','cualquier'];

let contextMsg = '';
if (testWords.some(w => _norm(w) === normMsg || normMsg === _norm(w))) {
  contextMsg = 'Parece que esa respuesta fue de prueba 😄. Cuando estés listo, cuéntanos con algo más real 👇\n\n';
} else if (vagueWords.some(w => _norm(w) === normMsg || normMsg.includes(_norm(w)))) {
  contextMsg = 'Necesitamos información un poco más concreta para asignarte el asesor ideal 🙌. Inténtalo de nuevo 👇\n\n';
} else if (ambigWords.some(w => _norm(w) === normMsg || normMsg.includes(_norm(w)))) {
  contextMsg = 'Entendemos que puede haber varias opciones, pero necesitamos la opción principal para orientarte mejor 🎯 👇\n\n';
} else {
  contextMsg = 'Hmm, necesitamos una respuesta un poco más clara y específica para poder ayudarte mejor 😊. Intentemos de nuevo 👇\n\n';
}

const fallbacks = {
  tipo_empresa:      `Para entender mejor tu operación, ¿podrías contarme brevemente qué tipo de empresa tienen?\n(Por ejemplo: fabricante, distribuidor, comercializadora, mayorista, punto de venta o tienda.)`,
  rubro_sector:      `¿A qué tipo de productos o sector se dedican principalmente?\n(Ejemplo: alimentos, farmacéutico, agro, ferretería, veterinario, cosméticos, consumo masivo, etc.)`,
  alcance_operativo: `¿Cómo gestionan actualmente sus ventas o despachos?\n(Ejemplo: ventas directas desde un local, distribución a tiendas, preventa o pedidos por teléfono/WhatsApp, etc.)`,
  interes:           `¿Qué quisieran mejorar con una solución como Mobilvendor?\n(Ejemplo: control de inventario, visibilidad de ventas, facturación, seguimiento de entregas, manejo de clientes, etc.)`,
  correo_corporativo:`Por favor envíame tu correo electrónico y número de contacto para continuar.`
};

const question = fallbacks[pendingQ] || `Por favor responde la pregunta anterior para continuar 🙏`;
const msg = contextMsg + question;

return [{ json: { messageToSend: msg, finalMessage: msg, systemMessage: msg,
  _intent: { result: 'INVALIDA', pending_question: pendingQ } } }];

// Restaura los datos originales de Lookup MQL1
// para que Decide Mode reciba la fila correcta de Google Sheets
// y no reinicie el flujo desde cero
const originalData = $('Lookup MQL1').item.json;
return [{ json: originalData }];

// --- Leer fila existente o crear nuevo contacto ---
let row = {};
let isNewContact = false;

try {
  const lookup = $input.first();
  if (lookup?.json && Object.keys(lookup.json).length > 1) {
    row = lookup.json;
  } else {
    isNewContact = true;
    row = {};
  }
} catch {
  isNewContact = true;
  row = {};
}

// --- Helpers ---
const toBool = v => v === true || String(v).trim().toLowerCase() === "true";
// ✅ Regex mejorada: busca correo en cualquier parte del texto
const EMAIL_RX = /[\w.-]+@[\w-]+\.[\w.-]+/;

// ======================= TELÉFONO E.164 MULTI-PAÍS =======================
// Regex para detectar un candidato a número dentro de texto libre
const PHONE_RX = /[+\d][\d\s-]{7,}\d/;

// Normaliza strings: quita tildes y baja a minúsculas
const _deburr = (s="") => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
const _lower  = (s="") => _deburr(String(s)).toLowerCase();

// Mapa (nombre país -> ISO2). Añade los que necesites.
const COUNTRY_ALIASES = {
  "ecuador":"EC","venezuela":"VE","mexico":"MX","méxico":"MX","chile":"CL",
  "argentina":"AR","colombia":"CO","peru":"PE","perú":"PE","bolivia":"BO",
  "paraguay":"PY","uruguay":"UY","panama":"PA","panamá":"PA","costa rica":"CR",
  "guatemala":"GT","honduras":"HN","el salvador":"SV","nicaragua":"NI","cuba":"CU",
  "republica dominicana":"DO","república dominicana":"DO","dominicana":"DO"
};

// ISO2 -> código de país (sin '+')
const DIAL_CODES = {
  EC:"593", VE:"58", MX:"52", CL:"56", AR:"54", CO:"57", PE:"51", BO:"591",
  PY:"595", UY:"598", PA:"507", CR:"506", GT:"502", HN:"504", SV:"503",
  NI:"505", CU:"53", DO:"1"
};

// País con 0 troncal típico al mostrar local
const TRUNK_ZERO_COUNTRIES = new Set(["EC","VE"]);

// Obtiene ISO2 por defecto desde row (si hay), si no EC
function resolveDefaultISO2() {
  const c = (row.pais || row.Country || "").trim();
  if (!c) return "EC";
  const iso = COUNTRY_ALIASES[_lower(c)];
  return iso || "EC";
}

// Convierte a E.164 (devuelve "" si no hay dígitos suficientes)
function toE164(raw, iso2) {
  if (!raw) return "";
  const defISO = iso2 || resolveDefaultISO2();
  const dial = DIAL_CODES[defISO] || "593";

  let s = String(raw).trim();

  // Si viene "texto con número", intenta extraer el primer candidato
  const rxHit = s.match(PHONE_RX);
  if (rxHit) s = rxHit[0];

  // Limpieza general
  const hadPlus = s.trim().startsWith("+");
  let digits = s.replace(/\D/g, "");   // deja solo dígitos

  // 00 internacional → +...
  if (!hadPlus && digits.startsWith("00")) {
    digits = digits.slice(2);
    return digits.length >= 8 && digits.length <= 15 ? ("+"+digits) : "";
  }

  // Si ya venía con + (o ya trae el país como prefijo), normaliza
  if (hadPlus) {
    const d = s.replace(/[^\d]/g, "");
    return d.length >= 8 && d.length <= 15 ? ("+"+d) : "";
  }

  // Si ya trae el código del país por delante (p.ej., 5939XXXXXXXX)
  if (digits.startsWith(dial)) {
    const d = digits;
    return d.length >= 8 && d.length <= 15 ? ("+"+d) : "";
  }

  // Quita un 0 troncal inicial (09..., 0412..., etc.)
  if (digits.startsWith("0")) digits = digits.slice(1);

  // Une con el código por defecto
  const joined = dial + digits;
  return joined.length >= 8 && joined.length <= 15 ? ("+"+joined) : "";
}

// === Mostrar teléfono "local" (sin prefijo) y con 0 troncal cuando aplique ===
function e164ToLocal(e164) {
  if (!e164) return "";
  const iso = resolveDefaultISO2();
  const dial = DIAL_CODES[iso] || "593";

  // Deja solo dígitos, quita prefijo del país si viene
  let d = String(e164).replace(/\D/g, "");
  if (d.startsWith("00")) d = d.slice(2);
  if (d.startsWith(dial)) d = d.slice(dial.length);

  // Agregar "0" troncal en países que lo usan comúnmente
  if (TRUNK_ZERO_COUNTRIES.has(iso) && !d.startsWith("0")) {
    d = "0" + d; // EC: 09..., VE: 0XXX...
  }
  return d;
}

// --- Captura mensaje y teléfono ---
const waMsg = $('WhatsApp Trigger1').item.json.messages?.[0] || {};
const userMessage =
  waMsg.text?.body ||
  waMsg.button?.payload ||
  waMsg.button?.text ||
  waMsg.interactive?.button_reply?.title ||
  waMsg.interactive?.list_reply?.title ||
  waMsg.interactive?.list_reply?.description ||
  "";

const rawPhone = $('WhatsApp Trigger1').item.json.messages?.[0]?.from || "";
const phone = rawPhone.startsWith('+') ? rawPhone : `+${rawPhone}`;

// --- Estado base ---
const currentState = {
  MQL1: toBool(row.MQL1),
  MQL2: toBool(row.MQL2),
  tipo_empresa: row.tipo_empresa || "",
  rubro_sector: row.rubro_sector || "",
  alcance_operativo: row.alcance_operativo || "",
  interes: row.interes || "",
  correo_corporativo: row.correo_corporativo || "",
  email: row.email || "",
  // ⬇️ Teléfono ahora se guarda en E.164
  phone: toE164(phone),
  new_phone: row.new_phone || "",
  attemps: row.attemps ? parseInt(row.attemps) : 0,
  current_step: row.current_step ? parseInt(row.current_step) : 0,
  pending_question: row.pending_question || "",
  needContact: false
};

// --- Generar mensaje de confirmación ---
function buildConfirmMessage(cs) {
  const correo = cs.email || "no registrado";

  // ⬇️ Mostrar SIN prefijo país y con 0 troncal si aplica
  const chosen = (cs.new_phone && String(cs.new_phone).trim() !== "")
    ? toE164(cs.new_phone)
    : (cs.phone ? toE164(cs.phone) : "");

  const telLocal = chosen ? e164ToLocal(chosen) : "no registrado";

  return `Solo para asegurarnos de que tus datos estén correctos y el asesor pueda contactarte, ¿podrías confirmarme con Si o No si tu correo electrónico es: ${correo} y tu número de contacto es: ${telLocal} por favor?`;
}

// --- Validar si tiene ambos datos de contacto ---
function hasCompleteContact(cs) {
  const hasEmail = cs.email && cs.email.trim() !== "";
  const hasPhone = (cs.new_phone && String(cs.new_phone).trim() !== "") || 
                   (cs.phone && cs.phone.trim() !== "");
  return hasEmail && hasPhone;
}

// --- Validación del paso de contacto ---
if (currentState.pending_question === "correo_corporativo") {
  const val = (userMessage || "").trim();
  const lower = val.toLowerCase();

  // 1️⃣ Usuario responde "no" → solicita nuevos datos
  if (["no", "no.", "negativo"].includes(lower)) {
    currentState.needContact = true;
    const msg = "Por favor envíame tu correo electrónico y número de contacto correctos para continuar.";
    return {
      json: {
        mode: "awaiting_new_contact",
        currentState,
        systemMessage: msg,
        finalMessage: msg
      }
    };
  }

  // 2️⃣ Usuario confirma "sí" → FINALIZA flujo (solo si tiene ambos datos)
  if (["si", "sí", "ok", "vale", "confirmado", "correcto"].includes(lower)) {
    if (hasCompleteContact(currentState)) {
      const closing = `🎉 Gracias por la información 🙏\nNuestro equipo comercial se pondrá en contacto contigo muy pronto.`;
      return {
        json: {
          mode: "completed",
          userConfirmedContact: true,
          MQL1: true,
          MQL2: true,
          currentState,
          systemMessage: closing,
          finalMessage: closing
        }
      };
    } else {
      // Si confirma pero faltan datos, solicita lo que falta
      const missing = [];
      if (!currentState.email || currentState.email.trim() === "") missing.push("correo electrónico");
      if (!currentState.new_phone && (!currentState.phone || currentState.phone.trim() === "")) missing.push("número de contacto");
      const msg = `Me falta tu ${missing.join(" y ")}. Por favor envíamelo para continuar.`;
      return {
        json: {
          mode: "awaiting_new_contact",
          currentState,
          systemMessage: msg,
          finalMessage: msg
        }
      };
    }
  }

  // 3️⃣ Usuario envía correo, teléfono o ambos
  const emailMatch = val.match(EMAIL_RX);

  // ⬇️ Intentar normalizar cualquier número del mensaje a E.164
  const normalizedCandidate = toE164(val);
  const hasPhone = !!normalizedCandidate;

  // Extraer y guardar correo
  if (emailMatch) {
    currentState.email = emailMatch[0];
    currentState.correo_corporativo = emailMatch[0];
  }

  // Extraer y guardar teléfono (E.164)
  if (hasPhone) {
    currentState.new_phone = normalizedCandidate;
  }

  // 4️⃣ Validar si ahora tiene datos completos
  if (emailMatch || hasPhone) {
    // Si ya tiene ambos datos, pedir confirmación (mostrando número local)
    if (hasCompleteContact(currentState)) {
      const confirmMsg = buildConfirmMessage(currentState);
      return {
        json: {
          mode: "reconfirm_contact",
          currentState,
          MQL1: false,
          systemMessage: confirmMsg,
          finalMessage: confirmMsg
        }
      };
    } else {
      // Si solo tiene uno, pedir el que falta
      const missing = [];
      if (!currentState.email || currentState.email.trim() === "") missing.push("correo electrónico");
      if (!currentState.new_phone && (!currentState.phone || currentState.phone.trim() === "")) missing.push("número de contacto");
      const msg = `Perfecto, recibí tu ${emailMatch ? "correo" : "número"}. Ahora por favor envíame tu ${missing.join(" y ")}.`;
      return {
        json: {
          mode: "awaiting_new_contact",
          currentState,
          systemMessage: msg,
          finalMessage: msg
        }
      };
    }
  }

  // 5️⃣ Si no detectó correo ni teléfono válidos
  const msg = "No logré identificar un correo o teléfono válido 😅. Por favor envíame tu correo electrónico y/o número de contacto correctos.";
  return {
    json: {
      mode: "awaiting_new_contact",
      currentState,
      systemMessage: msg,
      finalMessage: msg
    }
  };
}

// --- Preguntas previas ---
// ═══════════════════════════════════════════════════
// DETECTOR DE RESPUESTAS INVÁLIDAS v5
// Capa 1: palabras cortas con word-boundary
// Capa 2: frases evasivas / desvío al asesor
// Capa 3: insultos y lenguaje ofensivo
// ═══════════════════════════════════════════════════
const EVASIVAS_EXACT = ['na','nada','no','ningun','ninguno','ninguna'];

const EVASIVAS_PARTIAL = [
  'no tengo','no hay','no aplica','no se','no sé','n/a',
  'no tenemos','no hay nada','no tengo empresa','no tengo nada',
  'no tengo info','no tengo datos',
  'trabajo desde casa','desde casa','en casa','home office','freelance',
  'soy independiente','solo yo','yo solo','soy solo yo',
  'podria agendar','podría agendar','agendar una reunion','agendar una reunión',
  'hablar con alguien','hablar con un asesor','quiero hablar','contactar asesor',
  'un asesor','con un asesor','necesito un asesor','quiero un asesor','quisiera un asesor',
  'quiero que me llamen','que me llamen','me llamen',
  'que me contacten','me contacten','pueden contactarme',
  'prefiero que me llamen','quiero ser contactado',
  'bigo live','bigo','live id','no work',
  'no se decirte','no lo se','no lo sé','desconozco',
  'cualquier cosa','lo que sea','me da igual','no importa','soy nuevo'
];

const INSULTOS = [
  'idiota','idi0ta','estupido','imbecil','maldito','mierda','mierd4',
  'puta','puto','pendejo','culo','cabron','marica','inutil','hdp','ctm',
  'gonorrea','hijueputa','joder','jodas','jodete','jodido','jodida',
  'carajo','a la mierda','vete a la','fastidies','basura','asco',
  'porqueria','estafa','estafadores','ladrones','ladron',
  'mentirosos','mentiroso','inservible','verga','chingada','chinga',
  'huevon','huevona','malparido','malparida','cono','cojon','cojones',
  'zorra','perra','payaso','ridiculo','tarado','tarada','maldicion',
  'jod4s','ki me jod','que me jod','no me jod','m13rda','put4','p3ndejo'
];

function _norm(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
}

function isEvasive(text) {
  const raw = (text || '').trim();
  if (!raw || raw.length < 3) return true;
  const lower = _norm(raw);
  for (const w of EVASIVAS_EXACT) {
    if (new RegExp('\\b' + _norm(w) + '\\b').test(lower)) return true;
  }
  for (const w of EVASIVAS_PARTIAL) { if (lower.includes(_norm(w))) return true; }
  for (const w of INSULTOS)         { if (lower.includes(_norm(w))) return true; }
  return false;
}


const questions = [
  {
    key: 'tipo_empresa',
    question: `Gracias 🙌
Para entender mejor tu operación, ¿podrías contarme brevemente qué tipo de empresa tienen?
(Por ejemplo: fabricante, distribuidor, comercializadora, mayorista, punto de venta o tienda.)`,
    validator: t => !isEvasive(t) && (t || "").trim().length >= 3
  },
  {
    key: 'rubro_sector',
    question: `Perfecto, gracias por confirmarlo.
¿A qué tipo de productos o sector se dedican principalmente?
(Ejemplo: alimentos, farmacéutico, agro, ferretería, veterinario, cosméticos, consumo masivo, etc.)`,
    validator: t => !isEvasive(t) && (t || "").trim().length >= 3
  },
  {
    key: 'alcance_operativo',
    question: `Entendido 👌
¿Cómo gestionan actualmente sus ventas o despachos?
(Ejemplo: ventas directas desde un local, distribución a tiendas, preventa o pedidos por teléfono/WhatsApp, etc.)`,
    validator: t => !isEvasive(t) && (t || "").trim().length >= 3
  },
  {
    key: 'interes',
    question: `Gracias por la info 🙏
Y para orientarte mejor, ¿qué quisieran mejorar con una solución como Mobilvendor?
(Ejemplo: control de inventario, visibilidad de ventas, facturación, seguimiento de entregas, manejo de clientes, etc.)`,
    validator: t => !isEvasive(t) && (t || "").trim().length >= 3
  }
];

// --- Procesar pregunta pendiente ---
if (currentState.pending_question && currentState.pending_question !== "correo_corporativo" && userMessage.trim()) {
  const q = questions.find(q => q.key === currentState.pending_question);
  if (q && q.validator(userMessage)) {
    currentState[q.key] = userMessage.trim();
    currentState.pending_question = "";
    currentState.current_step++;
  }
}

// --- Determinar siguiente paso ---
const missing = questions.filter(q => !currentState[q.key]);
if (!currentState.pending_question && missing.length > 0) {
  currentState.pending_question = missing[0].key;
}

// --- Si completó los primeros 4 pasos ---
const hasFour = questions.every(q => currentState[q.key]);
if (hasFour && !currentState.correo_corporativo) {
  currentState.pending_question = "correo_corporativo";
}

// --- Inicio con "Sí" ---
if (userMessage.trim().toUpperCase() === "SI" && currentState.current_step === 0) {
  const firstQ = questions[0];
  const intro = `${firstQ.question}`;
  return { json: { mode: "start", systemMessage: intro, finalMessage: intro, currentState } };
}

// --- Continuar flujo normal ---
const nextQ = questions.find(q => q.key === currentState.pending_question);

// ⚠️ FIX: cuando toca correo_corporativo y aún no tiene email guardado,
// pedir el correo/teléfono en lugar de mostrar la confirmación con "no registrado"
if (!nextQ && (!currentState.email || currentState.email.trim() === "")) {
  const requestMsg = "Para que nuestro asesor pueda contactarte, por favor envíame tu correo electrónico y número de teléfono de contacto 📧📱";
  return {
    json: {
      mode: "awaiting_contact",
      currentState,
      nextQuestion: "correo_corporativo",
      systemMessage: requestMsg,
      finalMessage: requestMsg
    }
  };
}

return {
  json: {
    mode: "qualification",
    currentState,
    nextQuestion: nextQ ? nextQ.key : "correo_corporativo",
    systemMessage: nextQ ? nextQ.question : buildConfirmMessage(currentState),
    finalMessage: nextQ ? nextQ.question : buildConfirmMessage(currentState)
  }
};

/**
 * Extract Chat Data1 (CLEAN VERSION)
 * 
 * Ajustado a la estructura actual del archivo MQL
 */
function digitsOnly(s) {
  if (s === null || s === undefined) return "";
  if (typeof s === "number") return String(s).replace(/\D/g, "");
  if (typeof s === "string") return s.replace(/\D/g, "");
  if (typeof s === "object") return JSON.stringify(s).replace(/\D/g, ""); // Maneja objetos y arrays
  return "";
}

// ======================= TELÉFONO E.164 MULTI-PAÍS =======================
// Regex para detectar un candidato a número dentro de texto libre
const PHONE_RX = /[+\d][\d\s-]{7,}\d/;

// Normaliza strings: quita tildes y baja a minúsculas
const _deburr = (s="") => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
const _lower  = (s="") => _deburr(String(s)).toLowerCase();

// Alias de país (texto → ISO2). Amplía según necesites.
const COUNTRY_ALIASES = {
  "ecuador":"EC","venezuela":"VE","mexico":"MX","méxico":"MX","chile":"CL",
  "argentina":"AR","colombia":"CO","peru":"PE","perú":"PE","bolivia":"BO",
  "paraguay":"PY","uruguay":"UY","panama":"PA","panamá":"PA","costa rica":"CR",
  "guatemala":"GT","honduras":"HN","el salvador":"SV","nicaragua":"NI","cuba":"CU",
  "republica dominicana":"DO","república dominicana":"DO","dominicana":"DO"
};

// ISO2 → código país (sin '+')
const DIAL_CODES = {
  EC:"593", VE:"58", MX:"52", CL:"56", AR:"54", CO:"57", PE:"51", BO:"591",
  PY:"595", UY:"598", PA:"507", CR:"506", GT:"502", HN:"504", SV:"503",
  NI:"505", CU:"53", DO:"1"
};

// Resuelve el país por defecto desde el contexto previo; si no, EC
function resolveDefaultISO2(prev, cs) {
  const cand = (cs.pais || prev.pais || prev.Country || "").trim();
  if (!cand) return "EC";
  const iso = COUNTRY_ALIASES[_lower(cand)];
  return iso || "EC";
}

// Convierte cualquier entrada a E.164. Devuelve "" si no hay suficientes dígitos.
function toE164(raw, prev, cs) {
  if (!raw) return "";
  const iso2 = resolveDefaultISO2(prev, cs);
  const dial = DIAL_CODES[iso2] || "593";

  let s = String(raw).trim();

  // Si viene "texto con número", intenta extraer el primer candidato
  const rxHit = s.match(PHONE_RX);
  if (rxHit) s = rxHit[0];

  // Limpieza general
  const hadPlus = s.trim().startsWith("+");
  let digits = s.replace(/\D/g, ""); // solo dígitos

  // 00 internacional → +...
  if (!hadPlus && digits.startsWith("00")) {
    digits = digits.slice(2);
    return digits.length >= 8 && digits.length <= 15 ? ("+" + digits) : "";
  }

  // Si ya venía con +, normaliza
  if (hadPlus) {
    const d = s.replace(/[^\d]/g, "");
    return d.length >= 8 && d.length <= 15 ? ("+" + d) : "";
  }

  // Si ya trae el código país por delante (p.ej., 5939XXXXXXXX)
  if (digits.startsWith(dial)) {
    const d = digits;
    return d.length >= 8 && d.length <= 15 ? ("+" + d) : "";
  }

  // Quita 0 troncal (09..., 0412..., etc.)
  if (digits.startsWith("0")) digits = digits.slice(1);

  // Une con el código por defecto
  const joined = dial + digits;
  return joined.length >= 8 && joined.length <= 15 ? ("+" + joined) : "";
}

// --- Obtener datos básicos del trigger ---
const trigger = $('WhatsApp Trigger1').item;
const msgFrom = (trigger?.json?.messages?.[0]?.from) || "";
const contactWaId = (trigger?.json?.contacts?.[0]?.wa_id) || "";
const phoneRaw = msgFrom || contactWaId || "";
const phone = digitsOnly(phoneRaw); // sin prefijo de país (mantengo tu salida original)

// --- Recuperar contexto previo ---
let prev = {};
try { prev = $input.first()?.json ?? {}; } catch (e) { prev = {}; }

const cs = prev.currentState || {};

// --- Adaptación: new_phone a E.164 multi-país ---
// (antes: forzaba 593; ahora: normaliza con país por defecto del contexto)
let newPhone = cs.new_phone || "";
if (newPhone) {
  const e164 = toE164(newPhone, prev, cs);
  newPhone = e164 || ""; // si no se pudo normalizar, deja vacío
}

// --- Preparar salida limpia para Google Sheets ---
const out = {
  phone, // número limpio sin '+', se mantiene tal cual en tu diseño
  tipo_empresa: cs.tipo_empresa || "",
  rubro_sector: cs.rubro_sector || "",
  alcance_operativo: cs.alcance_operativo || "",
  interes: cs.interes || "",
  correo_corporativo: cs.correo_corporativo || "",
  email: cs.email || "",
  new_phone: newPhone, // ahora en formato E.164 (+NNN...)
  MQL1: typeof prev.MQL1 !== "undefined" ? prev.MQL1 : (cs.MQL1 ?? false),
  attemps: Number.isFinite(Number(cs.attemps)) ? Number(cs.attemps) : 0,
  current_step: cs.current_step ?? 0,
  pending_question: cs.pending_question ?? "",
  mode: prev.mode || "qualification",
  last_message: prev.userMessage || "",
  skipUpdate: prev.skipUpdate ?? false
};

// =============================================================
//     LÓGICA FINAL MQL1 CONTROLADA POR CONFIRMACIÓN DE CONTACTO
// =============================================================

// Señal de confirmación de correo + teléfono
out.userConfirmedContact = prev.userConfirmedContact === true;

// SI EL USUARIO TODAVÍA NO HA CONFIRMADO → MQL1 = SIEMPRE FALSE
if (!out.userConfirmedContact) {
    out.MQL1 = false;
    out.MQL2 = false;
} 
else {
    // ---- Solo después de la confirmación: aplicar la lógica final ----

    // 1️⃣ OK debe ser TRUE en Google Sheet
    let okValue = String($('Lookup MQL1').item.json.OK || "").trim().toLowerCase();
    let okIsTrue = okValue === "true";

    // 2️⃣ Todas las preguntas + email + teléfono deben estar completas
    let preguntasCompletas =
      cs.tipo_empresa &&
      cs.rubro_sector &&
      cs.alcance_operativo &&
      cs.interes &&
      cs.email &&
      (cs.new_phone || cs.phone);

    preguntasCompletas = !!preguntasCompletas;

    // 3️⃣ MQL1 SOLO = TRUE SI (OK = TRUE) Y (PREGUNTAS COMPLETAS = TRUE)
    out.MQL1 = okIsTrue && preguntasCompletas;

    // 4️⃣ MQL2 depende de MQL1
    out.MQL2 = out.MQL1 ? true : false;
}

return [{ json: out }];

