// ── Utilidad de normalización ─────────────────────────────────────────────
function _norm(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
}
const normTxt = _norm(texto);

// ── Listas de detección global ────────────────────────────────────────────
const testWords  = ['prueba','test','hola','hello','hi','hey','demo','probando','123','asdf','qwerty','abc'];
const vagueWords = ['ninguna','ninguno','no se','no sé','nada','no tengo','desconozco','no lo se','no lo sé'];
const ambigWords = ['todas','todos','varias','varios','cualquiera','todo','de todo','cualquier'];
const insultos   = ['idiota','estupido','imbecil','maldito','mierda','puta','puto','pendejo',
                    'culo','cabron','marica','inutil','hdp','ctm','joder','carajo','basura',
                    'asco','estafadores','mentiroso','verga','huevon','malparido','cono','perra'];

