const EVASIVAS_EXACT = ['na','nada','no','ningun','ninguno','ninguna'];

const EVASIVAS_PARTIAL = [
  'no tengo','no hay','no aplica','no se','no sé','n/a',
  'no tenemos','no hay nada','no tengo empresa','no tengo nada',
  'no tengo info','no tengo datos',
