const INSULTOS = [
  'idiota','idi0ta','estupido','imbecil','maldito','mierda','mierd4',
  'puta','puto','pendejo','culo','cabron','marica','inutil','hdp','ctm',
  'gonorrea','hijueputa','joder','jodas','jodete','jodido','jodida',
