  'huevon','huevona','malparido','malparida','cono','cojon','cojones',
  'zorra','perra','payaso','ridiculo','tarado','tarada','maldicion',
  'jod4s','ki me jod','que me jod','no me jod','m13rda','put4','p3ndejo'
];

function _norm(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
}

function isEvasive(text) {
  const raw = (text || '').trim();
  if (!raw || raw.length < 3) return true;
  const lower = _norm(raw);
  for (const w of EVASIVAS_EXACT) {
    if (new RegExp('\\b' + _norm(w) + '\\b').test(lower)) return true;
  }
  for (const w of EVASIVAS_PARTIAL) { if (lower.includes(_norm(w))) return true; }
  for (const w of INSULTOS)         { if (lower.includes(_norm(w))) return true; }
  return false;
}


